cat > vitest.config.ts <<'EOF'
import { defineConfig } from 'vitest/config';

// Rapier ships a CommonJS "main" inside an ESM package, which Node cannot load.
// Tests therefore resolve the ES build directly; the Vite app build already picks it.
export default defineConfig({
  resolve: {
    alias: { '@dimforge/rapier3d-compat': '@dimforge/rapier3d-compat/rapier.es.js' },
  },
});
EOF
npx vitest run src/game 2>&1 | tail -45
